var nums = [3, 2, 4];
var target = 6;
var seen = {};
for (var i = 0; i < nums.length; i++) {
  var need = target - nums[i];
  if (seen.hasOwnProperty(need)) {
    console.log([seen[need], i]);
    break;
  }
  seen[nums[i]] = i;
}
